code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A hollow 3x3 square is marked at its four outside diagonal corners.
    for r in range(h - 2):
        for c in range(w - 2):
            ring = [(r,c),(r,c+1),(r,c+2),(r+1,c),(r+1,c+2),(r+2,c),(r+2,c+1),(r+2,c+2)]
            if all(grid[y][x] == 1 for y,x in ring) and grid[r+1][c+1] == 7:
                for rr, cc in ((r-1,c-1),(r-1,c+3),(r+3,c-1),(r+3,c+3)):
                    if 0 <= rr < h and 0 <= cc < w:
                        out[rr][cc] = 2
                return out
    # Otherwise mark a complete solid 2x2 square along its four sides.
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or (r,c) in seen:
                continue
            comp, stack = [], [(r,c)]
            seen.add((r,c))
            while stack:
                y,x = stack.pop()
                comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            ys,xs=[p[0] for p in comp],[p[1] for p in comp]
            if len(comp)==4 and max(ys)-min(ys)==1 and max(xs)-min(xs)==1:
                top,left=min(ys),min(xs)
                for rr in range(max(0,top-1),min(h,top+3)):
                    for cc in range(max(0,left-1),min(w,left+3)):
                        if (top<=rr<top+2 or left<=cc<left+2) and out[rr][cc]==7:
                            out[rr][cc]=2
                return out
    return out
'''
